sys_script.script:
// Block saving a line if it would take the header over its Allocated Amount.
(function executeRule(current /*, previous*/ ) {

    // === API names you already use ===
    var LINES_TABLE = 'x_1797098_pettyc_0_petty_cash_lines';
    var HEADER_TABLE = 'x_1797098_pettyc_0_pettycashmain';
    var REF_TO_HEADER = 'pettycashmain_ref'; // line -> header reference
    var LINE_AMOUNT = 'total_line_amount'; // amount on the line
    var HDR_ALLOCATED = 'amount'; // allocated amount on header

    function toNum(v) {
        var n = parseFloat(v);
        return isNaN(n) ? 0 : n;
    }

    function r2(n) {
        return Math.round(n * 100) / 100;
    }

    var headerId = current.getValue(REF_TO_HEADER);
    if (!headerId) return; // nothing to validate

    // Get header allocated amount
    var hdr = new GlideRecord(HEADER_TABLE);
    if (!hdr.get(headerId)) return;
    var allocated = toNum(hdr.getValue(HDR_ALLOCATED));

    // Sum all other lines for this header
    var sumOther = 0;
    var gr = new GlideRecord(LINES_TABLE);
    gr.addQuery(REF_TO_HEADER, headerId);
    if (current.operation() === 'update') {
        gr.addQuery('sys_id', '!=', current.getUniqueValue());
    }
    gr.query();
    while (gr.next()) {
        sumOther += toNum(gr.getValue(LINE_AMOUNT));
    }

    var thisLine = toNum(current.getValue(LINE_AMOUNT));
    var projectedTotal = r2(sumOther + thisLine);

    // If you want to permit reimbursed amount to extend the ceiling:
    // var allocated = toNum(hdr.getValue(HDR_ALLOCATED)) + toNum(hdr.getValue('amount_reimbursed'));

    if (projectedTotal > allocated) {
        var remaining = r2(allocated - sumOther);
        if (remaining < 0) remaining = 0;

        gs.addErrorMessage(
            'Cannot save: this invoice would exceed the Allocated Amount. ' +
            'Allocated = ' + allocated.toFixed(2) + ', ' +
            'Current total of other lines = ' + sumOther.toFixed(2) + ', ' +
            'Remaining available = ' + remaining.toFixed(2) + '.'
        );
        current.setAbortAction(true); // prevent insert/update
    }

})(current);
